function canGrowTo(sx: number, sy: number, tx: number, ty: number): boolean {
  while (tx >= sx && ty >= sy) {
    if (tx === sx && ty === sy) return true;
    if (tx === ty) return false;
    if (tx > ty) tx -= ty;
    else ty -= tx;
  }
  return false;
}

